COMMIT;

SELECT (SELECT count(*) FROM app.usuarios WHERE email LIKE '%@demo.zonamatch.ar') AS usuarios_demo,
       (SELECT count(*) FROM app.resenas r JOIN app.usuarios u ON u.id = r.usuario_id WHERE u.email LIKE '%@demo.zonamatch.ar') AS resenas,
       (SELECT count(*) FROM app.preguntas p JOIN app.usuarios u ON u.id = p.usuario_id WHERE u.email LIKE '%@demo.zonamatch.ar') AS preguntas,
       (SELECT count(*) FROM app.respuestas r JOIN app.usuarios u ON u.id = r.usuario_id WHERE u.email LIKE '%@demo.zonamatch.ar') AS respuestas,
       (SELECT count(*) FROM app.aportes a JOIN app.usuarios u ON u.id = a.usuario_id WHERE u.email LIKE '%@demo.zonamatch.ar') AS aportes;
